3. Input board is 9x9 list of lists, with digits 1-9 or '.' for empty.
ANSWER: def is_valid_sudoku(board):
    # Check rows
    for row in board:
        seen = set()
        for num in row:
            if num != '.':
                if num in seen:
                    return False
                seen.add(num)
    # Check columns
    for j in range(9):
        seen = set()
        for i in range(9):
            num = board[i][j]
            if num != '.':
                if num in seen:
                    return False
                seen.add(num)
    # Check 3x3 boxes
    for box_i in range(3):
        for box_j in range(3):
            seen = set()
            for i in range(3):
                for j in range(3):
                    num = board[box_i*3 + i][box_j*3 + j]
                    if num != '.':
                        if num in seen:
                            return False
                        seen.add(num)
